cd /sdcard/Nexus_Brain/nexus_vault/08_hooks_attention && python3 -c "
import re
with open('Master_Visual_Hook_Design.md') as f:
    content = f.read()
lines = content.split('\n')
print(f'Total lines: {len(lines)}')

# Find sections
secs = {
    '§4': ('## §4 —', '## §5 —'),
    '§7': ('## §7 —', '## §8 —'),
    '§10': ('## §10 —', '## §11 —'),
    '§15': ('## §15 —', '## §16 —'),
}

def count_words(text):
    text = re.sub(r'#{1,6}\s+', '', text)
    text = re.sub(r'---+\s*', '', text)
    words = re.findall(r'[\w\u0600-\u06FF]+', text)
    return len(words)

total = count_words(content)
results = {}
for name, (start_marker, end_marker) in secs.items():
    s = content.find(start_marker)
    e = content.find(end_marker)
    if s >= 0:
        sec_text = content[s:e] if e >= 0 else content[s:]
        c = count_words(sec_text)
        results[name] = c
        print(f'{name}: {c} words ({c/total*100:.1f}%)')

# Verify §7 expansion anchors
for anchor_text in ['### 7.4', '### 7.5', '### 7.6']:
    if anchor_text in content:
        print(f'  ✓ §7 expanded with {anchor_text}')

for anchor_text in ['### 4.28', '### 4.29', '### 4.30', '### 4.31']:
    if anchor_text in content:
        print(f'  ✓ §4 expanded with {anchor_text}')

for anchor_text in ['### قالب: هوك أخبار عاجلة', '### قالب: هوك تحديث شخصي', '### قالب: هوك تحدي']:
    if anchor_text in content:
        print(f'  ✓ §10 expanded with {anchor_text}')

for anchor_text in ['### 15.10', '### 15.11', '### 15.12', '### 15.13', '### 15.14', '### 15.15']:
    if anchor_text in content:
        print(f'  ✓ §15 expanded with {anchor_text}')

print(f'\\nTotal: {total} words')
print(f'§4: {results.get(\"§4\", 0)} words ({results.get(\"§4\", 0)/total*100:.1f}%)')
print(f'§15: {results.get(\"§15\", 0)} words')
print(f'§4 >= 40%? {\"✅\" if results.get(\"§4\", 0)/total >= 0.4 else \"❌\"} ({results.get(\"§4\", 0)/total*100:.1f}%)')
print(f'§15 >= 1800? {\"✅\" if results.get(\"§15\", 0) >= 1800 else \"❌\"} ({results.get(\"§15\", 0)} words)')
print(f'Total >= 10000? {\"✅\" if total >= 10000 else \"❌\"} ({total} words)')
"

